const box = (o: object) => new Box(o as any);
const row = box({ width: 300, height: 50, direction: 'row', gap: 10, padding: 5 });
row.add(box({ width: 40, height: 10 })).add(box({ width: 60, height: 10 }));
const growRow = box({ width: 300, height: 50, direction: 'row', gap: 10, padding: 5 });
growRow.add(box({ width: 40 })).add(box({ grow: 1 })).add(box({ grow: 2 }));
const col = box({ width: 100, height: 200, direction: 'column', gap: 6, padding: 4 });
col.add(box({ height: 30 })).add(box({ grow: 1 })).add(box({ height: 20 }));
const none = box({ width: 100, height: 100 });
const inner = box({ x: 7, y: 9, width: 30, height: 20, direction: 'column', padding: 2 });
none.add(inner); inner.add(box({ height: 5 }));
const grid = new Grid({ width: 100, height: 100, padding: 4, gap: 2 });
[0, 1, 2].forEach(() => grid.add(box({})));
const tight = box({ width: 50, height: 50, direction: 'row', padding: 5 });
tight.add(box({ width: 100 })).add(box({ grow: 1 }));
const stray = box({ width: 80, height: 40, direction: 'row', gap: 3 });
stray.add(box({ width: 10 })).add(new Canvas({ x: 9, y: 9, width: 4, height: 4 })).add(box({ width: 20 }));
Object.assign(globalThis, { box, row, growRow, col, none, grid, tight, stray });
